"""Write docs/reference/skills.md from the skills that ship in this repository.

The list is built from each `.agents/skills/<name>/SKILL.md` front matter, so it
cannot describe a skill that is not here. Run with `--check` to fail when the
list is out of date. Standard library only.
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

OUTPUT = "docs/reference/skills.md"
SKILLS = ".agents/skills"
HEADER = (
    "<!-- Generated by tools/list_skills.py from the SKILL.md files. "
    "Edit a skill's description, then regenerate. -->\n"
)


class SkillError(Exception):
    """A skill folder whose front matter cannot be listed."""


def front_matter(text: str) -> str:
    match = re.match(r"---\n(.*?)\n---\n", text, re.DOTALL)
    return match.group(1) if match else ""


def field(front: str, key: str) -> str:
    lines = front.splitlines()
    for index, line in enumerate(lines):
        if not line.startswith(f"{key}:"):
            continue
        value = line[len(key) + 1 :].strip()
        if value[:1] in (">", "|"):
            block = []
            for extra in lines[index + 1 :]:
                if extra.strip() and not extra.startswith((" ", "\t")):
                    break
                block.append(extra.strip())
            return " ".join(part for part in block if part)
        if len(value) > 1 and value[0] == value[-1] == '"':
            return re.sub(r"\\(.)", r"\1", value[1:-1])
        if len(value) > 1 and value[0] == value[-1] == "'":
            return value[1:-1].replace("''", "'")
        return value
    return ""


def description(front: str) -> str:
    return field(front, "description")


def build(root: Path) -> str:
    folders = sorted(p for p in (root / SKILLS).iterdir() if p.is_dir())
    items = []
    for folder in folders:
        skill_file = folder / "SKILL.md"
        if not skill_file.is_file():
            raise SkillError(f"{folder.name}: no SKILL.md")
        front = front_matter(skill_file.read_text(encoding="utf-8"))
        if field(front, "name") != folder.name:
            raise SkillError(
                f"{folder.name}: front matter name does not match the folder"
            )
        summary = description(front)
        if not summary:
            raise SkillError(f"{folder.name}: no description")
        link = f"../../{SKILLS}/{folder.name}/SKILL.md"
        items.append(f"- [**{folder.name}**]({link}): {summary}")
    intro = (
        f"{len(items)} skills ship in `{SKILLS}/`. Each line is the skill's own "
        "description, which is what an agent reads to decide whether to load it."
    )
    return f"{HEADER}\n# Skills\n\n{intro}\n\n" + "\n".join(items) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--root", type=Path, default=Path(__file__).resolve().parent.parent
    )
    parser.add_argument(
        "--check", action="store_true", help="fail if the list is out of date"
    )
    args = parser.parse_args(argv)
    try:
        text = build(args.root)
    except SkillError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    target = args.root / OUTPUT
    current = target.read_text(encoding="utf-8") if target.is_file() else None
    if args.check:
        if current != text:
            print(f"{OUTPUT} is out of date; run python3 tools/list_skills.py")
            return 1
        print(f"{OUTPUT} is up to date")
        return 0
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8")
    print(f"wrote {OUTPUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
